import pathlib,json,datetime,os
from capture_v1 import C,load,dump,pin
D=C/'deliverables';L='SKODA-WORKING';m=load(D/f'Roadmark-RECOVERY-MANIFEST-{L}-20261015.json');docs=load(C/'library-documents-results.json')['results'];ars=load(C/'library-archives-results.json')['results'];assert len(docs)==4 and len(ars)==len(m['newArchives']);review=load(C/'INDEPENDENT-DELIVERY-DOCUMENT-CHECK.json');assert review['result']=='PASS';assert load(C/'DELIVERABLE-PRIVACY-GATE-v2.json')['result']=='PASS'
for r in docs+ars:
 p=pathlib.Path(r['local_path']);assert r['status']=='succeeded' and r['local_metadata_applied'] and os.getxattr(p,'user.library-file-id').decode()==r['library_file_id'] and os.getxattr(p,'user.library-file-version').decode()==str(r['current_version_number'])
x={'createdAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':m['status'],'source':m['source'],'newArchives':m['newArchives'],'baseRecovery':m['baseRecovery'],'workState':m['workState'],'verificationScope':m['verificationScope'],'counts':m['incrementalVerification'],'documents':[{'filename':r['file_name'],'library_file_id':r['library_file_id'],'version':r['current_version_number'],**pin(pathlib.Path(r['local_path']))} for r in docs],'independentVerification':m['independentVerification'],'preSaveDocumentVerification':review,'privacySummary':{'newArchiveGate':pin(C/'ALL-ARCHIVE-PRIVACY-GATE.json'),'newDocumentGate':pin(C/'DELIVERABLE-PRIVACY-GATE-v2.json'),'unclassifiedResiduals':0,'limitations':'Exact bounded content/rule and known-value checks, not universal secret-free assurance.'},'originalRawCaptureReplayCompatibility':m['originalRawCaptureReplayCompatibility'],'sourceSanitation':m['sourceSanitation'],'copyOnlySanitation':m['copyOnlySanitation'],'savingAnnouncement':load(C/'SAVING-ANNOUNCEMENT.json'),'noSourceOrStatusMutationByBackup':True,'noDeletionOrReplacement':True}
continuation=load(C/'DOCUMENT-PRIVACY-CONTINUATION-ADDENDUM-v1.json');x['documentPrivacyContinuation']={'classification':load(C/'INDEPENDENT-SKODA-DOCUMENT-CODE-CANDIDATE-CLASSIFICATION-v1.json'),'addendum':continuation,'cleanGate':load(C/'DELIVERABLE-PRIVACY-GATE-v2.json'),'originalFailedGate':load(C/'DELIVERABLE-PRIVACY-GATE.json'),'originalFailedTerminal':load(C/'scan-documents.resources.json'),'supportFiles':[{'filename':n,**pin(C/n),'text':(C/n).read_text()} for n in continuation['supportFiles']]}
if (C/'DELIVERY-CONFIRMATION.json').exists():x['deliveryConfirmation']=load(C/'DELIVERY-CONFIRMATION.json')
p=D/f'Roadmark-RECOVERY-ACTIVE-STATE-{L}-20261015.json';dump(p,x);dump(C/'library-active-request.json',{'uploads':[{'local_path':str(p),'purpose':'create_library_file','library_artifact_type':'report'}]})

